import "io" for File, Stat

File.create("stat_dev_a.temp") {|f| f.writeBytes("a") }
File.create("stat_dev_b.temp") {|f| f.writeBytes("b") }
var a = Stat.path("stat_dev_a.temp")
var b = Stat.path("stat_dev_b.temp")
System.print(a.device == b.device) // expect: true
File.delete("stat_dev_a.temp")
File.delete("stat_dev_b.temp")
